import sqlite3;c=sqlite3.connect('canon.db')
def has(t,code): return c.execute(f"select 1 from {t} where code=?",(code,)).fetchone()
def add(cat,code,o,f,r,refs,jaar=None,tp=None,weet=None):
  if has('canon',code): return 0
  c.execute("insert into canon(categorie,onderwerp,feit,status,reden,hangt_samen_met,ronde,code,verwijst_naar,jaar,tijdperk,weet) values(?,?,?,'voorlopig',?,?,10,?,?,?,?,?)",(cat,o,f,r,refs,code,refs,jaar,tp,weet));return 1
