n=0
for (code,f,jaar,ber,reg,tit,wie,oorz,actie,reac,won,verl,verz,off,echt,links,mag) in E:
  refs=';'.join(x for x in [oorz,links] if x)
  feit=(f"Jaar {ber} · Regio: {reg} · Wie: {wie}. Oorzaak: {oorz or '—'}. Actie: {actie} Reactie / onbedoeld gevolg: {reac} "
        f"Won: {won}. Verloor: {verl}. Verzet: {verz}. Officiële versie: {off} Wat echt gebeurde: {echt}")
  if mag: feit+=" [Hangt af van de nog niet goedgekeurde magietheorie (bloedafstand = kracht); voorlopig.]"
  n+=add('Geschiedenis',code,tit,feit,'Ronde 10: actie-reactieketen',refs,jaar,TP[f],'officieel: '+off)
